from harvests import load_harvests, ROWS
from progress import running_kilos, final_kilos

VALUES = [v for _, v in ROWS]


def test_length():
    assert len(running_kilos(list(load_harvests()))) == len(ROWS)


def test_final():
    assert final_kilos(list(load_harvests())) == sum(VALUES)


def test_first_entry():
    assert running_kilos(list(load_harvests()))[0] == VALUES[0]


def test_single():
    assert running_kilos(list(load_harvests())[:1]) == [VALUES[0]]


def test_empty():
    assert running_kilos([]) == [] and final_kilos([]) == 0
